import os
for root, dirs, files in os.walk('/workspace'):
    # Skip memory dirs
    dirs[:] = [d for d in dirs if d != 'memory' and not d.startswith('.')]
    for f in files:
        p = os.path.join(root, f)
        if f.lower().endswith('.pdf') or 'S1359' in f:
            print(p, os.path.getsize(p))
